@IterationMachine.iter_primitive_unfold
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (I A : Type) (step : I -> PTreeDefinition.ptree E MN (I + A))
         (n : nat) (t : PTreeDefinition.ptree E MN (I + A)),
       @BindScheduling.equiv MF FI FO (UnifiedFrontier.stable_head E MN A)
         (@IterationMachine.iter_primitive_approx E MN MF FI MX FO I A step n t)
         match @PTreeDefinition.observe E MN (I + A) t with
         | @PTreeDefinition.RetF _ _ _ _ (@inl _ _ i) =>
             @IterationMachine.iter_after E MN MF FI MX FO I A step n (step i)
         | @PTreeDefinition.RetF _ _ _ _ (@inr _ _ a) =>
             @Measure.sem_ret MF FI (UnifiedFrontier.stable_head E MN A)
               (@UnifiedFrontier.FHRet E MN A a)
         | @PTreeDefinition.TauF _ _ _ _ u =>
             @IterationMachine.iter_after E MN MF FI MX FO I A step n u
         | @PTreeDefinition.VisF _ _ _ _ X e k =>
             @Measure.sem_ret MF FI (UnifiedFrontier.stable_head E MN A)
               (@UnifiedFrontier.FHVis E MN A X e
                  (fun x : X => @IterationMachine.iter_active E MN I A step (k x)))
         | @PTreeDefinition.ProbF _ _ _ _ X mu k =>
             @Mixed.mixed_bind MN MF MX X (UnifiedFrontier.stable_head E MN A) mu
               (fun x : X => @IterationMachine.iter_after E MN MF FI MX FO I A step n (k x))
         end

@IterationMachine.iter_primitive_tree
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (I A : Type) (step : I -> PTreeDefinition.ptree E MN (I + A))
         (n : nat) (t : PTreeDefinition.ptree E MN (I + A)),
       @BindScheduling.equiv MF FI FO (UnifiedFrontier.stable_head E MN A)
         (@IterationMachine.iter_primitive_approx E MN MF FI MX FO I A step n t)
         (@PTreeKernel.ptree_hitting_approx E MN MF FI MX FO A n
            (@PTreeDefinition.observe E MN A (@IterationMachine.iter_active E MN I A step t)))

@IterationMachine.iter_phase_grid_split
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
