@IterationMachine.iter_phase_grid_le_primitive
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (I A : Type) (step : I -> PTreeDefinition.ptree E MN (I + A))
         (n m : nat) (t : PTreeDefinition.ptree E MN (I + A)),
       @Omega.sem_le MF FI FO (UnifiedFrontier.stable_head E MN A)
         (@IterationMachine.iter_phase_grid E MN MF FI MX FO I A step n m t)
         (@IterationMachine.iter_primitive_approx E MN MF FI MX FO I A step ((n + 1) * (m + 1)) t)

@IterationMachine.iter_primitive_le_phase_grid
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
