@IterationMachine.iter_phase_diagonal_tree
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (I A : Type) (step : I -> PTreeDefinition.ptree E MN (I + A)),
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       forall (t : PTreeDefinition.ptree E MN (I + A))
         (out : MF (UnifiedFrontier.stable_head E MN A)),
       @Omega.sem_lub MF FI FO (UnifiedFrontier.stable_head E MN A)
         (fun n : nat => @IterationMachine.iter_phase_grid E MN MF FI MX FO I A step n n t) out <->
       @PTreeKernel.ptree_stable_hitting E MN MF FI MX FO A
         (@PTreeDefinition.observe E MN A (@IterationMachine.iter_active E MN I A step t)) out

@IterationMachine.iter_phase_grid_row_lub
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO) (I A : Type)
         (step : I -> PTreeDefinition.ptree E MN (I + A)),
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       forall (Select : @Omega.SemanticOmegaSelection MF FI FO) (n : nat)
         (t : PTreeDefinition.ptree E MN (I + A)),
       @Omega.sem_lub MF FI FO (UnifiedFrontier.stable_head E MN A)
         (fun m : nat => @IterationMachine.iter_phase_grid E MN MF FI MX FO I A step n m t)
         (@PrimitiveStableHitting.stable_hitting_approx MF FI FO
            (PTreeDefinition.ptree E MN (I + A)) (UnifiedFrontier.stable_head E MN A)
            (@IterationMachine.iter_machine_kernel E MN MF FI MX FO Ord I A step Select) n t)

@IterationMachine.iter_machine_hitting_sound
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO),
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (I A : Type) (step : I -> PTreeDefinition.ptree E MN (I + A)),
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       forall (Select : @Omega.SemanticOmegaSelection MF FI FO)
         (t : PTreeDefinition.ptree E MN (I + A)) (out : MF (UnifiedFrontier.stable_head E MN A)),
       @PrimitiveStableHitting.stable_hitting MF FI FO (PTreeDefinition.ptree E MN (I + A))
         (UnifiedFrontier.stable_head E MN A)
         (@IterationMachine.iter_machine_kernel E MN MF FI MX FO Ord I A step Select) t out ->
       @PTreeKernel.ptree_stable_hitting E MN MF FI MX FO A
         (@PTreeDefinition.observe E MN A (@IterationMachine.iter_active E MN I A step t)) out

@IterationUniform.peutt_iter_active_rel
     : forall (E MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (I J A B : Type) (f : I -> PTreeDefinition.ptree E MN (I + A))
         (g : J -> PTreeDefinition.ptree E MN (J + B)) (SI : I -> J -> Prop)
         (RR : A -> B -> Prop),
       (forall (i : I) (j : J),
        SI i j ->
        @PEutt.peutt E MN MF FI FC MX FO (I + A) (J + B)
          (@PStruct.pstruct_iter_sum_rel I J A B SI RR) (f i) (g j)) ->
       forall (t : PTreeDefinition.ptree E MN (I + A)) (u : PTreeDefinition.ptree E MN (J + B)),
       @PEutt.peutt E MN MF FI FC MX FO (I + A) (J + B)
         (@PStruct.pstruct_iter_sum_rel I J A B SI RR) t u ->
       @PEutt.peutt E MN MF FI FC MX FO A B RR (@IterationMachine.iter_active E MN I A f t)
         (@IterationMachine.iter_active E MN J B g u)

